using System.Buffers.Binary;
using Rakion.Core.Enums;

namespace Rakion.Core.Packets;

/// <summary>
/// Parsed representation of a client UDP NAT probe / keep-alive datagram.
/// Wire layout (23 bytes total):
///   [0..1]   ushort Opcode (0x0201 or 0x0202)
///   [2..5]   uint   Sequence / TransactionId
///   [6]      byte   Flag
///   [7..8]   ushort UserIndex
///   [9..12]  uint   UserId (Session Ticket)
///   [13..16] uint   Ip
///   [17..18] ushort Port
///   [19..22] uint   Cookie (Random probe nonce generated by client)
/// Evidence: Observed in Rakion.bin 0x00473A90..0x00473C90 and RakionWorldServ.exe 0x00425D80 / 0x00425FA0.
/// </summary>
public sealed record UdpProbeRequest(
    ushort Opcode,
    uint Sequence,
    byte Flag,
    ushort UserIndex,
    uint UserId,
    uint Ip,
    ushort Port,
    uint Cookie);

/// <summary>
/// Helper for parsing and serializing UDP hole punch probe packets (Opcodes 0x0201 and 0x0202).
/// Server response layout (12 bytes):
///   [0..1]   ushort Opcode (always 0x0201)
///   [2..5]   uint   Cookie (echoed from request)
///   [6]      byte   PortFlag1 (0 for port 40708 / UDP1, 1 for port 40709 / UDP2)
///   [7]      byte   PortFlag2 (0 for port 40708 / UDP1, 1 for port 40709 / UDP2)
///   [8..11]  uint   Cookie (echoed from request)
/// Evidence: Observed in RakionWorldServ.exe 0x00425F5C..0x00425F75 and 0x0042611D..0x0042613E.
/// </summary>
public static class UdpProbePacket
{
    public const int RequestHeaderSize = 7;
    public const int RequestPayloadSize = 16;
    public const int RequestTotalSize = RequestHeaderSize + RequestPayloadSize; // 23 bytes
    public const int ResponseSize = 12;

    public static bool TryParseRequest(ReadOnlySpan<byte> datagram, out UdpProbeRequest request)
    {
        if (datagram.Length < RequestTotalSize)
        {
            request = default!;
            return false;
        }

        ushort opcode = BinaryPrimitives.ReadUInt16LittleEndian(datagram[..2]);
        uint sequence = BinaryPrimitives.ReadUInt32LittleEndian(datagram[2..6]);
        byte flag = datagram[6];

        ushort userIndex = BinaryPrimitives.ReadUInt16LittleEndian(datagram[7..9]);
        uint userId = BinaryPrimitives.ReadUInt32LittleEndian(datagram[9..13]);
        uint ip = BinaryPrimitives.ReadUInt32LittleEndian(datagram[13..17]);
        ushort port = BinaryPrimitives.ReadUInt16LittleEndian(datagram[17..19]);
        uint cookie = BinaryPrimitives.ReadUInt32LittleEndian(datagram[19..23]);

        request = new UdpProbeRequest(opcode, sequence, flag, userIndex, userId, ip, port, cookie);
        return true;
    }

    public static byte[] CreateResponse(uint cookie, byte portFlag)
    {
        byte[] response = new byte[ResponseSize];
        WriteResponse(cookie, portFlag, response);
        return response;
    }

    public static void WriteResponse(uint cookie, byte portFlag, Span<byte> destination)
    {
        if (destination.Length < ResponseSize)
        {
            throw new ArgumentException($"Destination span too small for UDP probe response (expected {ResponseSize} bytes).", nameof(destination));
        }

        // Response opcode is always 0x0201 for both ports in retail RakionWorldServ
        BinaryPrimitives.WriteUInt16LittleEndian(destination[..2], (ushort)ClientOpcode.UdpHolePunch1);
        BinaryPrimitives.WriteUInt32LittleEndian(destination[2..6], cookie);

        destination[6] = portFlag;
        destination[7] = portFlag;

        BinaryPrimitives.WriteUInt32LittleEndian(destination[8..12], cookie);
    }
}

